<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/ecosystem.php';
$isGuestPreview = empty($_SESSION['user_id']);
if ($isGuestPreview) {
    // Keep the first-run experience useful to visitors and investors. Reading
    // today's content does not require an account; saving progress does.
    header('X-Beyond-Guest-Preview: DailyBreath');
    $beyondWallet = beyond_nav_bootstrap('DailyBreath', ['balance'=>0,'currency'=>'BITS','status'=>'guest']);
} else {
    $beyondWallet = beyond_app_bootstrap('DailyBreath');
}
$pdo = beyond_db();

require_once __DIR__ . '/includes/verse-of-day.php';
require_once __DIR__ . '/includes/web-app.php';
require_once __DIR__ . '/includes/sacred-text.php';
$faithTradition = dailybreath_faith_tradition((string)($_GET['faith'] ?? $_COOKIE['dailybreath_faith'] ?? 'bible'));
setcookie('dailybreath_faith', $faithTradition, ['expires'=>time()+31536000,'path'=>'/dailybreath/','samesite'=>'Lax']);
$faithLabel = dailybreath_tradition_label($faithTradition);
$dailyVerse = dailybreath_interfaith_verse_of_day($pdo, $faithTradition, (string)($_SESSION['locale'] ?? 'en'));
$dailyTitle = $dailyVerse['text'];
$dailyBody = $dailyVerse['reference'];
$dailyScriptureUrl = dailybreath_scripture_url($dailyVerse);
$devotional = null;
try {
    $query = $pdo->prepare('SELECT title,excerpt,scripture_reference,duration_minutes FROM devotionals WHERE is_published=1 AND locale=? AND publish_date=? ORDER BY id DESC LIMIT 1');
    $query->execute([$_SESSION['locale'] ?? 'en', date('Y-m-d')]);
    $devotional = $query->fetch(PDO::FETCH_ASSOC) ?: null;
} catch (Throwable $exception) {}
$devotional = $devotional ?: dailybreath_recovery_devotional_for_date(date('Y-m-d'), false)
    ?: dailybreath_recovery_devotional_for_date(date('Y-m-d'))
    ?: ['title'=>'Walk in Quiet Confidence','excerpt'=>'Make room for stillness and remember that God is present before your next step.','scripture_reference'=>'Psalm 46:10','duration_minutes'=>5];
$reflectionLabel = "Today’s devotional";
$reflectionLink = 'devotionals.php';
$reflectionAction = 'Read devotional';
if ($faithTradition === 'torah') {
    $reflectionLabel = "Today’s Jewish reflection";
    $reflectionLink = $dailyScriptureUrl;
    $reflectionAction = 'Read in Tanakh';
    $devotional = [
        'title'=>'Pause with Today’s Tanakh Passage',
        'excerpt'=>'Read the passage slowly, notice the word or phrase that stays with you, and carry it into one faithful action today.',
        'scripture_reference'=>$dailyVerse['reference'],
        'duration_minutes'=>3,
    ];
} elseif ($faithTradition === 'quran') {
    $reflectionLabel = "Today’s Quran reflection";
    $reflectionLink = $dailyScriptureUrl;
    $reflectionAction = 'Read in Quran';
    $devotional = [
        'title'=>'Pause with Today’s Ayah',
        'excerpt'=>'Read the ayah with attention, reflect on its guidance, and carry one sincere response into the day.',
        'scripture_reference'=>$dailyVerse['reference'],
        'duration_minutes'=>3,
    ];
}

$name = trim((string)($_SESSION['name'] ?? '')) ?: 'Friend';
?>
